$inspectQa = @'
import fs from 'node:fs';import path from 'node:path';import {redact} from './src/util.js';
const q=JSON.parse(fs.readFileSync('.dip-local/current-host-qa.json'));
const file=path.join(q.root,'turn-1-events.jsonl');
const lines=fs.existsSync(file)?fs.readFileSync(file,'utf8').trim().split('\n'):[];
const events=lines.flatMap(line=>{try{return[JSON.parse(line)]}catch{return[]}});
console.log(JSON.stringify({eventCount:events.length,types:events.slice(-8).map(e=>({type:e.type,itemType:e.item?.type,tool:e.item?.name || e.item?.tool,thread:e.thread_id}))}));
const err=path.join(q.root,'turn-1-stderr.txt'); if(fs.existsSync(err))console.log(redact(fs.readFileSync(err,'utf8').split('\n').filter(l=>/hook|trust|error|warn/i.test(l)).slice(-12).join('\n')).slice(0,1800));
'@
$inspectQa | node --disable-warning=ExperimentalWarning --input-type=module

